import { format, parse } from 'date-fns';

export interface ExtractedTicketInfo {
  eventName: string;
  eventDate: Date | null;
  eventTime: string;
  teams: {
    homeTeam: string;
    awayTeam: string;
  };
  league: string;
  betType: string;
  odds: string;
  ticketId: string;
}

export function parseTicketText(text: string): ExtractedTicketInfo {
  // In a real implementation, this would use NLP techniques to extract information
  // For demonstration, we'll parse the text based on patterns

  // Extract teams using regex
  const teamsRegex = /(\w+(\s\w+)*)\s+vs\.\s+(\w+(\s\w+)*)/i;
  const teamsMatch = text.match(teamsRegex);

  const homeTeam = teamsMatch?.[1] ?? 'Unknown Team';
  const awayTeam = teamsMatch?.[3] ?? 'Unknown Team';

  // Extract date and time using regex
  const dateRegex = /([A-Z][a-z]+\s\d{1,2},\s\d{4})\s+-\s+(\d{1,2}:\d{2}\s*[AP]M)/i;
  const dateMatch = text.match(dateRegex);

  let eventDate: Date | null = null;
  let eventTime = '';

  if (dateMatch) {
    try {
      eventDate = parse(`${dateMatch[1]} ${dateMatch[2]}`, 'MMMM d, yyyy h:mm a', new Date());
      eventTime = dateMatch[2];
    } catch (e) {
      console.error('Failed to parse date:', e);
    }
  }

  // Extract other details
  const leagueMatch = text.match(/Game:\s*(\w+)/i);
  const league = leagueMatch?.[1] ?? 'Sports';

  const betTypeMatch = text.match(/(\w+):\s*[\w\s\-\.]+\s*[+-]?\d+/i);
  const betType = betTypeMatch?.[1] ?? 'Bet';

  const oddsMatch = text.match(/[+-]\d+/);
  const odds = oddsMatch?.[0] ?? '';

  const ticketIdMatch = text.match(/Ticket ID:\s*([\w\-]+)/i);
  const ticketId = ticketIdMatch?.[1] ?? '';

  // Create event name
  const eventName = `${homeTeam} vs ${awayTeam}`;

  return {
    eventName,
    eventDate,
    eventTime,
    teams: {
      homeTeam,
      awayTeam
    },
    league,
    betType,
    odds,
    ticketId
  };
}

export function formatEventDescription(ticketInfo: ExtractedTicketInfo): string {
  return `
Watch Party for ${ticketInfo.teams.homeTeam} vs ${ticketInfo.teams.awayTeam}

Game Details:
• Sport: ${ticketInfo.league}
• Bet Type: ${ticketInfo.betType} ${ticketInfo.odds}
• Ticket ID: ${ticketInfo.ticketId}

Join Zoom Meeting:
https://zoom.us/j/12345678 (This is a demo link - an actual link would be generated)
Meeting ID: 123 4567 8901
Passcode: betscan
  `.trim();
}

