   257→
   258→          await this.saveSoldPositions();
   259→        }
   260→      }
   261→
   262→      await this.savePositions();
   263→      return txid;
   264→    } catch (error) {
   265→      logger.error(
   266→        `Error performing ${isBuy ? "buy" : "sell"}: ${error.message}`,
   267→        { error }
   268→      );
   269→      if (isBuy) {
   270→        this.buyingTokens.delete(token.token.mint);
   271→      } else {
   272→        this.sellingPositions.delete(token.token.mint);
   273→      }
   274→      return false;
   275→    }
   276→  }
   277→
   278→  async checkAndSellPosition(tokenMint) {
   279→    if (this.sellingPositions.has(tokenMint)) {
   280→    //  logger.info(`Already selling position for ${tokenMint}, skipping`);
   281→      return;
   282→    }
   283→
   284→    const position = this.positions.get(tokenMint);
   285→    if (!position) return;
   286→
   287→    const tokenData = await this.fetchTokenData(tokenMint);
